-- ===================================================================
-- REDE DE PRATO - SCRIPT DDL (ORACLE SQL)
-- Modelo alinhado às classes do backend Java / DDD.
-- Todas as chaves primárias usam NUMBER GENERATED BY DEFAULT AS IDENTITY.
-- ===================================================================

CREATE TABLE T_RP_ENDERECO (
    id_endereco  NUMBER GENERATED BY DEFAULT AS IDENTITY,
    logradouro   VARCHAR2(100) NOT NULL,
    numero       VARCHAR2(10),
    complemento  VARCHAR2(50),
    bairro       VARCHAR2(60) NOT NULL,
    cidade       VARCHAR2(60) NOT NULL,
    uf           CHAR(2) NOT NULL,
    cep          CHAR(8) NOT NULL,
    CONSTRAINT PK_RP_ENDERECO PRIMARY KEY (id_endereco),
    CONSTRAINT CK_RP_ENDERECO_UF CHECK (LENGTH(TRIM(uf)) = 2),
    CONSTRAINT CK_RP_ENDERECO_CEP CHECK (cep BETWEEN '00000000' AND '99999999')
);

CREATE TABLE T_RP_OFERTANTE (
    id_ofertante  NUMBER GENERATED BY DEFAULT AS IDENTITY,
    nome          VARCHAR2(100) NOT NULL,
    tipo          VARCHAR2(20) NOT NULL,
    telefone      VARCHAR2(15) NOT NULL,
    email         VARCHAR2(100),
    possui_selo   CHAR(1) DEFAULT 'N' NOT NULL,
    data_selo     DATE,
    ativo         CHAR(1) DEFAULT 'S' NOT NULL,
    id_endereco   NUMBER NOT NULL,
    CONSTRAINT PK_RP_OFERTANTE PRIMARY KEY (id_ofertante),
    CONSTRAINT FK_RP_OFERTANTE_ENDERECO FOREIGN KEY (id_endereco)
        REFERENCES T_RP_ENDERECO (id_endereco),
    CONSTRAINT CK_RP_OFERTANTE_TIPO CHECK (tipo IN ('SUPERMERCADO', 'FEIRANTE')),
    CONSTRAINT CK_RP_OFERTANTE_SELO CHECK (possui_selo IN ('S', 'N')),
    CONSTRAINT CK_RP_OFERTANTE_ATIVO CHECK (ativo IN ('S', 'N')),
    CONSTRAINT CK_RP_OFERTANTE_SELO_DATA CHECK (
        (possui_selo = 'S' AND data_selo IS NOT NULL)
        OR (possui_selo = 'N' AND data_selo IS NULL)
    )
);

CREATE TABLE T_RP_CATEGORIA_ALIMENTO (
    id_categoria  NUMBER GENERATED BY DEFAULT AS IDENTITY,
    nome          VARCHAR2(50) NOT NULL,
    descricao     VARCHAR2(200),
    CONSTRAINT PK_RP_CATEGORIA_ALIMENTO PRIMARY KEY (id_categoria),
    CONSTRAINT UQ_RP_CATEGORIA_NOME UNIQUE (nome)
);

CREATE TABLE T_RP_BENEFICIARIO (
    id_beneficiario  NUMBER GENERATED BY DEFAULT AS IDENTITY,
    nome             VARCHAR2(100) NOT NULL,
    tipo             VARCHAR2(20) NOT NULL,
    qtd_pessoas      NUMBER(4),
    telefone         VARCHAR2(15),
    ativo            CHAR(1) DEFAULT 'S' NOT NULL,
    id_endereco      NUMBER,
    CONSTRAINT PK_RP_BENEFICIARIO PRIMARY KEY (id_beneficiario),
    CONSTRAINT FK_RP_BENEFICIARIO_ENDERECO FOREIGN KEY (id_endereco)
        REFERENCES T_RP_ENDERECO (id_endereco),
    CONSTRAINT CK_RP_BENEFICIARIO_TIPO CHECK (
        tipo IN ('PESSOA', 'FAMILIA', 'INSTITUICAO', 'PEQUENO_NEGOCIO')
    ),
    CONSTRAINT CK_RP_BENEFICIARIO_QTD CHECK (
        (qtd_pessoas IS NULL OR qtd_pessoas > 0)
        AND (tipo <> 'PESSOA' OR qtd_pessoas = 1)
    ),
    CONSTRAINT CK_RP_BENEFICIARIO_ATIVO CHECK (ativo IN ('S', 'N'))
);

CREATE TABLE T_RP_PONTO_DISTRIBUICAO (
    id_ponto               NUMBER GENERATED BY DEFAULT AS IDENTITY,
    nome                   VARCHAR2(100) NOT NULL,
    tipo                   VARCHAR2(20) NOT NULL,
    dias_funcionamento     VARCHAR2(50) NOT NULL,
    horario_abertura       VARCHAR2(5) NOT NULL,
    horario_fechamento     VARCHAR2(5) NOT NULL,
    telefone               VARCHAR2(15),
    ativo                  CHAR(1) DEFAULT 'S' NOT NULL,
    id_endereco            NUMBER NOT NULL,
    CONSTRAINT PK_RP_PONTO_DISTRIBUICAO PRIMARY KEY (id_ponto),
    CONSTRAINT FK_RP_PONTO_ENDERECO FOREIGN KEY (id_endereco)
        REFERENCES T_RP_ENDERECO (id_endereco),
    CONSTRAINT CK_RP_PONTO_TIPO CHECK (
        tipo IN ('COZINHA_SOLIDARIA', 'ONG', 'ASSOCIACAO')
    ),
    CONSTRAINT CK_RP_PONTO_ATIVO CHECK (ativo IN ('S', 'N')),
    CONSTRAINT CK_RP_PONTO_HORARIOS CHECK (
        LENGTH(horario_abertura) = 5 AND LENGTH(horario_fechamento) = 5
    )
);

CREATE TABLE T_RP_LOTE (
    id_lote                    NUMBER GENERATED BY DEFAULT AS IDENTITY,
    id_ofertante               NUMBER NOT NULL,
    id_categoria               NUMBER NOT NULL,
    descricao                  VARCHAR2(200) NOT NULL,
    peso_kg                    NUMBER(8,2) NOT NULL,
    condicao                   VARCHAR2(20) NOT NULL,
    modalidade                 VARCHAR2(15) NOT NULL,
    preco                      NUMBER(10,2),
    valor_estimado             NUMBER(10,2),
    data_cadastro              DATE DEFAULT SYSDATE NOT NULL,
    data_limite_retirada       DATE NOT NULL,
    url_foto                   VARCHAR2(255),
    precisa_transporte         CHAR(1) DEFAULT 'N' NOT NULL,
    status                     VARCHAR2(15) DEFAULT 'DISPONIVEL' NOT NULL,
    CONSTRAINT PK_RP_LOTE PRIMARY KEY (id_lote),
    CONSTRAINT FK_RP_LOTE_OFERTANTE FOREIGN KEY (id_ofertante)
        REFERENCES T_RP_OFERTANTE (id_ofertante),
    CONSTRAINT FK_RP_LOTE_CATEGORIA FOREIGN KEY (id_categoria)
        REFERENCES T_RP_CATEGORIA_ALIMENTO (id_categoria),
    CONSTRAINT CK_RP_LOTE_PESO CHECK (peso_kg > 0),
    CONSTRAINT CK_RP_LOTE_CONDICAO CHECK (
        condicao IN ('BOA', 'MADURA', 'CONSUMO_IMEDIATO')
    ),
    CONSTRAINT CK_RP_LOTE_MODALIDADE CHECK (modalidade IN ('DOACAO', 'VENDA')),
    CONSTRAINT CK_RP_LOTE_PRECO CHECK (
        (modalidade = 'DOACAO' AND preco IS NULL)
        OR (modalidade = 'VENDA' AND preco > 0)
    ),
    CONSTRAINT CK_RP_LOTE_VALOR_ESTIMADO CHECK (
        valor_estimado IS NULL OR valor_estimado >= 0
    ),
    CONSTRAINT CK_RP_LOTE_DATAS CHECK (data_limite_retirada >= data_cadastro),
    CONSTRAINT CK_RP_LOTE_TRANSPORTE CHECK (precisa_transporte IN ('S', 'N')),
    CONSTRAINT CK_RP_LOTE_STATUS CHECK (
        status IN ('DISPONIVEL', 'RESERVADO', 'RETIRADO', 'EXPIRADO')
    )
);

CREATE TABLE T_RP_RESERVA (
    id_reserva        NUMBER GENERATED BY DEFAULT AS IDENTITY,
    id_lote           NUMBER NOT NULL,
    id_beneficiario   NUMBER NOT NULL,
    id_ponto          NUMBER,
    data_reserva      DATE DEFAULT SYSDATE NOT NULL,
    data_retirada     DATE,
    status            VARCHAR2(15) DEFAULT 'ATIVA' NOT NULL,
    CONSTRAINT PK_RP_RESERVA PRIMARY KEY (id_reserva),
    CONSTRAINT FK_RP_RESERVA_LOTE FOREIGN KEY (id_lote)
        REFERENCES T_RP_LOTE (id_lote),
    CONSTRAINT FK_RP_RESERVA_BENEFICIARIO FOREIGN KEY (id_beneficiario)
        REFERENCES T_RP_BENEFICIARIO (id_beneficiario),
    CONSTRAINT FK_RP_RESERVA_PONTO FOREIGN KEY (id_ponto)
        REFERENCES T_RP_PONTO_DISTRIBUICAO (id_ponto),
    CONSTRAINT CK_RP_RESERVA_STATUS CHECK (status IN ('ATIVA', 'RETIRADA', 'CANCELADA')),
    CONSTRAINT CK_RP_RESERVA_DATA CHECK (
        data_retirada IS NULL OR data_retirada >= data_reserva
    ),
    CONSTRAINT CK_RP_RESERVA_STATUS_DATA CHECK (
        (status = 'RETIRADA' AND data_retirada IS NOT NULL)
        OR (status IN ('ATIVA', 'CANCELADA') AND data_retirada IS NULL)
    )
);

-- Impede mais de uma reserva ATIVA para o mesmo lote, mas mantém o histórico
-- de reservas canceladas ou retiradas.
CREATE UNIQUE INDEX UX_RP_RESERVA_ATIVA_LOTE
    ON T_RP_RESERVA (CASE WHEN status = 'ATIVA' THEN id_lote END);

CREATE TABLE T_RP_DESTINACAO (
    id_destinacao       NUMBER GENERATED BY DEFAULT AS IDENTITY,
    id_lote             NUMBER NOT NULL,
    tipo                VARCHAR2(15) NOT NULL,
    peso_kg             NUMBER(8,2) NOT NULL,
    data_destinacao     DATE DEFAULT SYSDATE NOT NULL,
    CONSTRAINT PK_RP_DESTINACAO PRIMARY KEY (id_destinacao),
    CONSTRAINT FK_RP_DESTINACAO_LOTE FOREIGN KEY (id_lote)
        REFERENCES T_RP_LOTE (id_lote),
    CONSTRAINT CK_RP_DESTINACAO_TIPO CHECK (tipo IN ('CONSUMO', 'COMPOSTAGEM')),
    CONSTRAINT CK_RP_DESTINACAO_PESO CHECK (peso_kg > 0)
);

CREATE TABLE T_RP_ALERTA (
    id_alerta       NUMBER GENERATED BY DEFAULT AS IDENTITY,
    id_lote         NUMBER NOT NULL,
    tipo            VARCHAR2(15) NOT NULL,
    canal           VARCHAR2(15) NOT NULL,
    data_envio      DATE DEFAULT SYSDATE NOT NULL,
    CONSTRAINT PK_RP_ALERTA PRIMARY KEY (id_alerta),
    CONSTRAINT FK_RP_ALERTA_LOTE FOREIGN KEY (id_lote)
        REFERENCES T_RP_LOTE (id_lote) ON DELETE CASCADE,
    CONSTRAINT CK_RP_ALERTA_TIPO CHECK (tipo IN ('NOVO_LOTE', 'XEPA')),
    CONSTRAINT CK_RP_ALERTA_CANAL CHECK (canal IN ('APP', 'WHATSAPP'))
);

-- Índices auxiliares para as consultas e joins frequentes.
CREATE INDEX IX_RP_LOTE_OFERTANTE ON T_RP_LOTE (id_ofertante);
CREATE INDEX IX_RP_LOTE_CATEGORIA ON T_RP_LOTE (id_categoria);
CREATE INDEX IX_RP_RESERVA_BENEFICIARIO ON T_RP_RESERVA (id_beneficiario);
CREATE INDEX IX_RP_DESTINACAO_LOTE ON T_RP_DESTINACAO (id_lote);
CREATE INDEX IX_RP_ALERTA_LOTE ON T_RP_ALERTA (id_lote);

-- Regras implementadas no BO/backend:
-- 1. A soma das destinacoes de um lote nao pode ultrapassar T_RP_LOTE.peso_kg.
-- 2. A criacao/cancelamento de reserva deve atualizar o status do lote na mesma transacao.
-- 3. Os horarios sao validados no formato HH:MM pelo backend.
